  each('[data-joist]',b=>b.onclick=()=>{s.joist=b.dataset.joist;s.completed['joist-table']=false;this.refreshReading('[data-joist="'+s.joist+'"]');this.drawRoof();});
  each('[data-column]',b=>b.onclick=()=>{s.readColumn=b.dataset.column;this.refreshReading('[data-column="'+s.readColumn+'"]');});
  each('[data-g-depth]',b=>b.onclick=()=>{s.girderDepth=+b.dataset.gDepth;s.girderLoad=+b.dataset.gLoad;this.refreshReading('[data-g-depth="'+s.girderDepth+'"][data-g-load="'+s.girderLoad+'"]');this.drawRoof();});
  each('[data-unit]',b=>b.onclick=()=>this.change('unitAnswer',b.dataset.unit));each('[data-basis]',b=>b.onclick=()=>this.change('basisPick',b.dataset.basis));
  if(q('#srWidthAnswer'))q('#srWidthAnswer').oninput=e=>{s.widthAnswer=e.target.value;s.widthChecked=false;};
  q('#srNote').oninput=e=>{s.notes[s.lesson]=e.target.value;s.completed[s.lesson]=false;};
